# This file is not generated by Stainless and is preserved across codegen runs.
# It checks the requests and models of the bare metal global view methods. It also checks
# that the retained routes (images, rebuild, the temporary regional client and the
# Kubernetes flavor list) still send the legacy requests and return the legacy fields.
#
# The tests use respx, so they run under a plain `pytest` (or `scripts/test`) without the
# Steady mock server.
from __future__ import annotations

import json
import inspect
from typing import Any, List, Tuple, Callable, Iterator
from datetime import datetime, timezone

import httpx
import respx
import pytest

from gcore import Gcore, AsyncGcore
from gcore.types.cloud import BaremetalRegionalFlavor
from gcore.types.cloud.baremetal import BaremetalFlavor, BaremetalServer
from gcore.types.cloud.baremetal_regional import BaremetalRegionalServer

# respx intercepts the transport, so the host is irrelevant.
base_url = "http://127.0.0.1:4010"

SERVER_ID = "00000000-0000-4000-8000-000000000001"
SERVERS_PATH = "/cloud/v1/projects/1/baremetal/servers"
SERVER_PATH = f"{SERVERS_PATH}/{SERVER_ID}"
FLAVORS_PATH = "/cloud/v1/projects/1/baremetal/flavors"

Params = List[Tuple[str, str]]


@pytest.fixture(autouse=True)
def no_client_env(monkeypatch: pytest.MonkeyPatch) -> None:
    # the global routes need no region, so a region from the environment must not hide a missing one
    monkeypatch.delenv("GCORE_CLOUD_PROJECT_ID", raising=False)
    monkeypatch.delenv("GCORE_CLOUD_REGION_ID", raising=False)


def _client(*, strict: bool = False, cloud_region_id: int | None = None) -> Gcore:
    return Gcore(
        base_url=base_url,
        api_key="test",
        cloud_project_id=1,
        cloud_region_id=cloud_region_id,
        _strict_response_validation=strict,
    )


def _async_client(*, cloud_region_id: int | None = None) -> AsyncGcore:
    return AsyncGcore(
        base_url=base_url,
        api_key="test",
        cloud_project_id=1,
        cloud_region_id=cloud_region_id,
        _strict_response_validation=False,
    )


def _handler(request: httpx.Request) -> httpx.Response:
    if request.method == "GET" and request.url.path in (SERVERS_PATH, FLAVORS_PATH):
        return httpx.Response(200, json={"count": 0, "results": []})
    if request.method == "GET":
        return httpx.Response(200, json={})
    return httpx.Response(200, json={"tasks": ["task-1"]})


@pytest.fixture
def router() -> Iterator[respx.MockRouter]:
    with respx.mock(base_url=base_url) as mock:
        yield mock


def _requests(router: respx.MockRouter) -> list[httpx.Request]:
    # respx leaves `calls` untyped.
    calls: Any = router.calls
    return [call.request for call in calls]


def _params(request: httpx.Request) -> Params:
    return sorted(request.url.params.multi_items())


def _body(request: httpx.Request) -> Any:
    return json.loads(request.content)


# (operation, invoke, method, path). On an async client, invoke returns an awaitable.
_OPERATIONS: list[tuple[str, Callable[[Any], Any], str, str]] = [
    (
        "servers.create",
        lambda c: c.cloud.baremetal.servers.create(
            region_id=1, flavor_name="bm2-hf-small", image_id="image-1", interfaces=[{"port_id": "port-1"}]
        ),
        "POST",
        SERVERS_PATH,
    ),
    ("servers.list", lambda c: c.cloud.baremetal.servers.list(), "GET", SERVERS_PATH),
    ("servers.get", lambda c: c.cloud.baremetal.servers.get(SERVER_ID), "GET", SERVER_PATH),
    ("servers.update", lambda c: c.cloud.baremetal.servers.update(SERVER_ID, name="web-2"), "PATCH", SERVER_PATH),
    ("servers.delete", lambda c: c.cloud.baremetal.servers.delete(SERVER_ID), "DELETE", SERVER_PATH),
    (
        "servers.action",
        lambda c: c.cloud.baremetal.servers.action(SERVER_ID, action="reboot_hard"),
        "POST",
        f"{SERVER_PATH}/action",
    ),
    (
        "servers.console.get",
        lambda c: c.cloud.baremetal.servers.console.get(SERVER_ID),
        "GET",
        f"{SERVER_PATH}/console",
    ),
    ("flavors.list", lambda c: c.cloud.baremetal.flavors.list(), "GET", FLAVORS_PATH),
]
_OPERATION_IDS = [operation[0] for operation in _OPERATIONS]


# the client has a project but no region: the global routes need none
@pytest.mark.parametrize(("operation", "invoke", "method", "path"), _OPERATIONS, ids=_OPERATION_IDS)
def test_operation_uses_global_route(
    router: respx.MockRouter, operation: str, invoke: Callable[[Any], Any], method: str, path: str
) -> None:
    router.route(url__regex=r".+").mock(side_effect=_handler)
    invoke(_client())
    assert [(r.method, r.url.path) for r in _requests(router)] == [(method, path)], operation


@pytest.mark.parametrize(("operation", "invoke", "method", "path"), _OPERATIONS, ids=_OPERATION_IDS)
async def test_operation_uses_global_route_async(
    router: respx.MockRouter, operation: str, invoke: Callable[[Any], Any], method: str, path: str
) -> None:
    router.route(url__regex=r".+").mock(side_effect=_handler)
    await invoke(_async_client())
    assert [(r.method, r.url.path) for r in _requests(router)] == [(method, path)], operation


