def _page(request: httpx.Request) -> httpx.Response:
    """Return one item for each request, out of two items in total."""
    offset = int(request.url.params.get("offset", "0"))
    return httpx.Response(200, json={"count": 2, "results": [{"id": f"item-{offset}", "name": f"item-{offset}"}]})


# (list, invoke, path, params of the first page). The filters must stay on the next page.
_PAGED_LISTS: list[tuple[str, Callable[[Any], Any], str, Params]] = [
    (
        "servers.list",
        lambda c: c.cloud.baremetal.servers.list(limit=1, name={"contains": ["db"]}, region_ids=[1]),
        SERVERS_PATH,
        [("limit", "1"), ("name[contains]", "db"), ("region_ids", "1")],
    ),
    (
        "flavors.list",
        lambda c: c.cloud.baremetal.flavors.list(limit=1, compatible_with_image_id="image-1", region_ids=[1]),
        FLAVORS_PATH,
        [("compatible_with_image_id", "image-1"), ("limit", "1"), ("region_ids", "1")],
    ),
]
_PAGED_LIST_IDS = [paged[0] for paged in _PAGED_LISTS]


@pytest.mark.parametrize(("name", "invoke", "path", "first"), _PAGED_LISTS, ids=_PAGED_LIST_IDS)
def test_list_iterates_every_page(
    router: respx.MockRouter, name: str, invoke: Callable[[Any], Any], path: str, first: Params
) -> None:
    router.get(path).mock(side_effect=_page)
    items = [item.name for item in invoke(_client())]
    assert items == ["item-0", "item-1"], (name, first)


@pytest.mark.parametrize(("name", "invoke", "path", "first"), _PAGED_LISTS, ids=_PAGED_LIST_IDS)
async def test_list_iterates_every_page_async(
    router: respx.MockRouter, name: str, invoke: Callable[[Any], Any], path: str, first: Params
) -> None:
    router.get(path).mock(side_effect=_page)
    items = [item.name async for item in invoke(_async_client())]
    assert items == ["item-0", "item-1"], (name, first)


@pytest.mark.parametrize(("name", "invoke", "path", "first"), _PAGED_LISTS, ids=_PAGED_LIST_IDS)
def test_list_keeps_filters_on_next_page(
    router: respx.MockRouter, name: str, invoke: Callable[[Any], Any], path: str, first: Params
) -> None:
    router.get(path).mock(side_effect=_page)
    list(invoke(_client()))
    assert [_params(r) for r in _requests(router)] == [first, sorted([*first, ("offset", "1")])], name


@pytest.mark.parametrize(("name", "invoke", "path", "first"), _PAGED_LISTS, ids=_PAGED_LIST_IDS)
async def test_list_keeps_filters_on_next_page_async(
    router: respx.MockRouter, name: str, invoke: Callable[[Any], Any], path: str, first: Params
) -> None:
    router.get(path).mock(side_effect=_page)
    [item async for item in invoke(_async_client())]
    assert [_params(r) for r in _requests(router)] == [first, sorted([*first, ("offset", "1")])], name


