def _get_server(router: respx.MockRouter) -> BaremetalServer:
    router.get(SERVER_PATH).mock(return_value=httpx.Response(200, json=_SERVER))
    return _client(strict=True).cloud.baremetal.servers.get(SERVER_ID)


def test_server_model_reads_ports_and_bond_groups(router: respx.MockRouter) -> None:
    server = _get_server(router)
    assert [(i.port_id, i.port_group) for i in server.interfaces] == [("port-1", 0), ("port-2", 0), ("port-3", None)]


def test_server_model_reads_sub_port_parent(router: respx.MockRouter) -> None:
    server = _get_server(router)
    assert server.interfaces[1].to_dict()["trunk"] == {"parent_port_id": "port-1", "role": "sub_port"}


def test_server_model_keeps_dpu_nulls(router: respx.MockRouter) -> None:
    server = _get_server(router)
    assert server.interfaces[2].to_dict()["trunk"] is None and server.interfaces[2].port_group is None


def test_server_model_keeps_every_field(router: respx.MockRouter) -> None:
    server = _get_server(router)
    # Pydantic v1 and v2 write a UTC time in JSON in different forms, so compare the times as values
    assert server.created_at == datetime(2026, 11, 19, 10, 0, tzinfo=timezone.utc)
    assert server.updated_at == datetime(2026, 11, 19, 10, 5, tzinfo=timezone.utc)
    dumped = server.to_dict(mode="json")
    expected = dict(_SERVER)
    for key in ("created_at", "updated_at"):
        dumped.pop(key)
        expected.pop(key)
    assert dumped == expected


