def test_flavor_list_returns_global_flavor(router: respx.MockRouter) -> None:
    router.get(FLAVORS_PATH).mock(return_value=httpx.Response(200, json={"count": 1, "results": [_FLAVOR]}))
    flavors = _client(strict=True).cloud.baremetal.flavors.list()
    assert all(isinstance(f, BaremetalFlavor) for f in flavors.results)


